mapper.select:
SELECT id
FROM sre_rca_evaluation_run
WHERE status = 'QUEUED'
  AND next_attempt_at <= #{now}
  AND deadline_at > #{now}
ORDER BY next_attempt_at ASC, id ASC
LIMIT #{limit}

mapper.update:
UPDATE sre_rca_evaluation_run
SET status = 'RUNNING', attempts = attempts + 1,
    claimed_at = #{claimedAt}, heartbeat_at = #{claimedAt},
    started_at = COALESCE(started_at, #{claimedAt}), update_time = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND status = 'QUEUED'
  AND next_attempt_at <= #{claimedAt}
  AND deadline_at > #{claimedAt}

UPDATE sre_rca_evaluation_run
SET status = 'QUEUED', next_attempt_at = #{nextAttemptAt},
    claimed_at = NULL, heartbeat_at = NULL, update_time = CURRENT_TIMESTAMP
WHERE status = 'RUNNING'
  AND COALESCE(heartbeat_at, claimed_at, started_at, update_time) <= #{staleBefore}
  AND attempts < #{maxAttempts}
  AND deadline_at > #{nextAttemptAt}
